begin;
\ir fixtures/clinical.sql
reset role;
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(610),pg_temp.practice(),'Synthetic second clinic','Etc/UTC');
create function pg_temp.day3()returns date language sql as $$select(clock_timestamp()at time zone'Etc/UTC')::date+7$$;
create function pg_temp.type3(n integer default 30)returns jsonb language sql as $$select jsonb_build_object('name','Synthetic consultation — زيارة','duration_minutes',n,'buffer_before',10,'buffer_after',10,'capacity',1,'location_ids',jsonb_build_array(pg_temp.location(),pg_temp.id(610)),'active',true)$$;
create function pg_temp.book3(k integer,minute integer default 600,loc uuid default null,ver integer default 1)returns jsonb language sql as $$select public.doctor_book_consultation(pg_temp.practice(),coalesce(loc,pg_temp.location()),pg_temp.patient(),pg_temp.day3(),minute,1,1,pg_temp.id(k),pg_temp.id(600),ver)$$;
set local role authenticated;select pg_temp.claim(1);
select lives_ok($$select public.doctor_write_schedule(pg_temp.practice(),pg_temp.location(),0,jsonb_build_object('slot_minutes',10,'weekly',(select jsonb_agg(jsonb_build_object('weekday',d,'start',540,'end',1080))from generate_series(0,6)d),'exceptions','[]'::jsonb),pg_temp.id(601),1)$$,'configure source clinic');
select lives_ok($$select public.doctor_write_schedule(pg_temp.practice(),pg_temp.id(610),0,jsonb_build_object('slot_minutes',10,'weekly',(select jsonb_agg(jsonb_build_object('weekday',d,'start',540,'end',1080))from generate_series(0,6)d),'exceptions','[]'::jsonb),pg_temp.id(602),1)$$,'configure destination');
select is(public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(600),0,pg_temp.type3(),pg_temp.id(603))->>'version','1','DOS-M3-001-C01: explicit consultation revision');
select is(public.doctor_consultation_types(pg_temp.practice(),pg_temp.location())->>'capacity','1','single doctor has one commitment; no inferred group capacity');
select throws_ok($$select public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(600),1,pg_temp.type3()||'{"capacity":2}',pg_temp.id(604))$$,'22023','DOCTOR_CONSULTATION_INVALID','overbooking cannot be enabled by owner or metadata');
select is(public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(600),0,pg_temp.type3(),pg_temp.id(603))->>'version','1','same intent returns exact revision');
select throws_ok($$select public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(600),0,pg_temp.type3(40),pg_temp.id(603))$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','changed retry material rejected');
select pg_temp.put('booking3',pg_temp.book3(620));
select is(pg_temp.book3(620),pg_temp.v('booking3'),'book replay does not duplicate');
select throws_ok($$select pg_temp.book3(621,630,pg_temp.id(610))$$,'40001','DOCTOR_APPOINTMENT_CONFLICT','cross-location buffer overlap blocked');
select throws_ok($$select public.doctor_book_appointment(pg_temp.practice(),pg_temp.id(610),pg_temp.patient(),pg_temp.day3(),630,1,1,pg_temp.id(622))$$,'40001','DOCTOR_APPOINTMENT_CONFLICT','legacy booking also sees typed buffer');
select lives_ok($$select pg_temp.book3(623,650,pg_temp.id(610))$$,'half-open buffered boundary admits adjacent commitment');
select is((select value->>'available'from jsonb_array_elements(public.doctor_consultation_availability(pg_temp.practice(),pg_temp.id(610),pg_temp.day3(),pg_temp.id(600),1)->'slots')where(value->>'minute')::integer=630),'false','availability uses identical cross-location capacity rule');
select is((select value->>'reason'from jsonb_array_elements(public.doctor_consultation_availability(pg_temp.practice(),pg_temp.location(),pg_temp.day3(),pg_temp.id(600),1)->'slots')where(value->>'minute')::integer=540),'outside_hours','pre-buffer must fit inside opening windows');
select is(public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(600),1,pg_temp.type3(60),pg_temp.id(624))->>'version','2','config changes append revisions');
select throws_ok($$select pg_temp.book3(625,780)$$,'40001','DOCTOR_AVAILABILITY_CONFLICT','stale type cannot book');
select throws_ok($$select public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(600),1,pg_temp.type3(45),pg_temp.id(626))$$,'40001','DOCTOR_AVAILABILITY_CONFLICT','concurrent editor uses CAS');
select lives_ok($$select public.doctor_reschedule_appointment(pg_temp.practice(),pg_temp.location(),(pg_temp.v('booking3')->>'appointment_id')::uuid,1,pg_temp.id(610),pg_temp.day3(),800,1,1,'Synthetic move',pg_temp.id(627))$$,'reschedule retains booked type snapshot after config update');
select pg_temp.claim(3);
select throws_ok($$select public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(600),2,pg_temp.type3(),pg_temp.id(628))$$,'42501','DOCTOR_ACCESS_DENIED','secretary without independent scheduling grant denied');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_consultation_types(pg_temp.practice(),pg_temp.location())$$,'42501','DOCTOR_ACCESS_DENIED','independent doctor cannot read types');
reset role;
select is((select consultation_snapshot->>'duration_minutes'from public.appointments where id=(pg_temp.v('booking3')->>'appointment_id')::uuid),'30','DOS-M3-001-C02: original duration preserved');
select is((select count(*)::integer from public.consultation_types where id=pg_temp.id(600)),2,'history remains append-only');
select throws_ok($$update public.appointments set consultation_snapshot=consultation_snapshot||'{"buffer_after":0}'where id=(pg_temp.v('booking3')->>'appointment_id')::uuid$$,'22023','DOCTOR_CONSULTATION_SNAPSHOT_IMMUTABLE','snapshot cannot be silently rewritten');
select ok(doctor_private.schedule_instant('2027-03-28',90,'Europe/London')is null,'DOS-M3-001-C03: DST missing instant rejected');
select ok(doctor_private.schedule_instant('2027-10-31',90,'Europe/London')is null,'DST fold rejected');
set local role authenticated;select pg_temp.claim(1);
select lives_ok($$select public.doctor_write_schedule(pg_temp.practice(),pg_temp.location(),1,jsonb_build_object('slot_minutes',10,'weekly','[]'::jsonb,'exceptions',jsonb_build_array(jsonb_build_object('date',pg_temp.day3(),'closed',true,'windows','[]'::jsonb,'reason','Synthetic closure'))),pg_temp.id(630),1)$$,'closed exception explicit');
select is(jsonb_array_length(public.doctor_consultation_availability(pg_temp.practice(),pg_temp.location(),pg_temp.day3(),pg_temp.id(600),2)->'slots'),0,'closed-day exception offers no typed appointments');
reset role;
select ok(not has_table_privilege('authenticated','public.consultation_types','INSERT'),'direct type writes denied');
select ok(not has_function_privilege('anon','public.doctor_book_consultation(uuid,uuid,uuid,date,integer,integer,integer,uuid,uuid,integer)','EXECUTE'),'anonymous booking denied');
select ok(not has_function_privilege('authenticated','doctor_private.schedule_clock(date,integer,text)','EXECUTE'),'trusted location clock remains private');
select ok((select bool_and(doctor_private.schedule_clock(day,minute,zone)is not distinct from doctor_private.schedule_instant(day,minute,zone))from(values(date'2027-03-28','Europe/London'),(date'2027-10-31','Europe/London'),(date'2025-04-06','Australia/Lord_Howe'),(date'2025-10-05','Australia/Lord_Howe'),(date'2020-03-08','Antarctica/Casey'),(date'2011-12-30','Pacific/Apia'))d(day,zone)cross join unnest(array[0,90,105,120,135,180,1440])minute),'optimized location clock preserves checked missing/fold/skip semantics');
reset role;
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(611),pg_temp.practice(),'Synthetic retired clinic','Etc/UTC');
set local role authenticated;select pg_temp.claim(1);
select lives_ok($$select public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(650),0,pg_temp.type3()||jsonb_build_object('location_ids',jsonb_build_array(pg_temp.location(),pg_temp.id(611))),pg_temp.id(651))$$,'type initially includes another active clinic');
reset role;update public.locations set archived_at=clock_timestamp(),version=version+1 where id=pg_temp.id(611);
set local role authenticated;select pg_temp.claim(1);
select lives_ok($$select public.doctor_write_consultation_type(pg_temp.practice(),pg_temp.location(),pg_temp.id(650),1,pg_temp.type3()||jsonb_build_object('location_ids',jsonb_build_array(pg_temp.location())),pg_temp.id(652))$$,'archived clinic can be removed without rewriting historical type revision');
reset role;
select is((select cardinality(location_ids)from public.consultation_types where id=pg_temp.id(650)and version=1),2,'retired-clinic history remains intact');
select * from finish();rollback;
